using System.Data;
using Microsoft.Data.SqlClient;
using Wire = AccountingApp.Contracts;
namespace WinFormsApp2;

internal sealed partial class SchedulingService(string connectionString, UserSession user)
{
    private static void Id(SqlCommand c, string key, Guid? value) => c.Parameters.Add(key, SqlDbType.UniqueIdentifier).Value = (object?)value ?? DBNull.Value;
    private static void Time(SqlCommand c, string key, DateTime value) => SchedulingRules.Time(c, key, value);
    private static string Text(string text, int max) { text = text.Trim(); if (text.Length < 1 || text.Length > max || text.Any(char.IsControl)) throw new ArgumentException("Takvim metin alanlarını kontrol edin."); return text; }
    private static async Task<DataRow?> RowAsync(IUnitOfWork w, string table, string key, Guid id, CancellationToken ct)
    { using var c = w.Command($"SELECT * FROM dbo.{table} WITH(UPDLOCK,HOLDLOCK) WHERE {key}=@id"); Id(c, "@id", id); var data = await c.TableAsync(ct); return data.Rows.Count == 1 ? data.Rows[0] : null; }
    private static void Version(DataRow row, byte[] value) { if (!((byte[])row["RecordVersion"]).SequenceEqual(PersonnelConcurrency.RequireVersion(value))) throw new InvalidOperationException("Takvim kaydı değişmiş; yenileyin."); }
    private static void ProjectRow(DataRow row, Guid project) { if (row.Field<Guid>("ProjectId") != project) throw new UnauthorizedAccessException("Kayıt bu proje kapsamında değil."); }
    private static async Task ProjectRangeAsync(IUnitOfWork w, Guid project, Guid? team, DateTime start, DateTime end, CancellationToken ct)
    {
        using var c = w.Command(@"SELECT COUNT(*) FROM dbo.FinanceProjects WITH(UPDLOCK,HOLDLOCK) WHERE ProjectId=@project AND IsActive=1 AND (StartDate IS NULL OR StartDate<=@first) AND (EndDate IS NULL OR EndDate>=@last)
 AND (@team IS NULL OR EXISTS(SELECT 1 FROM dbo.ProjectTeams WITH(HOLDLOCK) WHERE TeamId=@team AND ProjectId=@project AND IsActive=1))"); Id(c, "@project", project); Id(c, "@team", team); c.Parameters.Add("@first", SqlDbType.Date).Value = start.Date; c.Parameters.Add("@last", SqlDbType.Date).Value = end.AddTicks(-1).Date; if (Convert.ToInt32(await c.ExecuteScalarAsync(ct)) != 1) throw new InvalidOperationException("Proje/ekip etkin değil veya takvim aralığı proje tarihlerini aşıyor.");
    }
    private static async Task<(Guid Employment, Guid Roster)> TargetAsync(IUnitOfWork w, Guid project, Guid? team, Guid person, PersonnelGroup group, byte[]? version, DateTime start, DateTime end, CancellationToken ct)
    {
        await SchedulingRules.LockPersonAsync(w, person, ct); Guid employment;
        using (var c = w.Command($"SELECT CurrentEmploymentId FROM {PersonnelRepository.Table(group)} WITH(UPDLOCK,HOLDLOCK) WHERE PersonId=@person AND ArchivedUtc IS NULL" + (version != null ? " AND RecordVersion=@version" : "")))
        { Id(c, "@person", person); if (version != null) c.Parameters.Add("@version", SqlDbType.Binary, 8).Value = PersonnelConcurrency.RequireVersion(version); employment = await c.ExecuteScalarAsync(ct) is Guid id ? id : throw new InvalidOperationException(PersonnelConcurrency.ConflictMessage); }
        await EmploymentService.ValidateRangeAsync(w, group, person, start.Date, end.AddTicks(-1).Date, ct);
        using var q = w.Command(@"SELECT TOP(1) A.AssignmentId FROM dbo.PersonnelProjectAssignments A WITH(UPDLOCK,HOLDLOCK) JOIN dbo.EmploymentRecordLinks L ON L.RecordKind=N'Assignment' AND L.RecordKey=CONVERT(nvarchar(64),A.AssignmentId)
 WHERE A.ProjectId=@project AND A.PersonId=@person AND A.PersonnelGroup=@group AND L.EmploymentId=@employment AND A.CancelledUtc IS NULL AND A.StartDate<=@first AND (A.EndDate IS NULL OR A.EndDate>=@last) AND (@team IS NULL OR A.TeamId=@team) ORDER BY A.StartDate,A.AssignmentId"); Id(q, "@project", project); Id(q, "@person", person); Id(q, "@employment", employment); Id(q, "@team", team); q.Parameters.Add("@group", SqlDbType.Int).Value = (int)group; q.Parameters.Add("@first", SqlDbType.Date).Value = start.Date; q.Parameters.Add("@last", SqlDbType.Date).Value = end.AddTicks(-1).Date; return (employment, await q.ExecuteScalarAsync(ct) is Guid roster ? roster : throw new InvalidOperationException("Personelin tüm aralığı kapsayan geçerli proje/ekip ataması yok."));
    }
    internal async Task SaveTemplateAsync(Wire.ShiftTemplateWrite input, CancellationToken ct)
    {
        if (DesktopConnection.IsRemote(connectionString)) { await RemoteApi.For(connectionString, user).Done("schedule/template", input, ct); return; }
        string name = Text(input.Name, 100), site = input.Site.Trim(); if (site.Length > 100 || site.Any(char.IsControl) || input.TemplateId == Guid.Empty || input.StartMinute is < 0 or >= 1440 || input.DurationMinutes is < 1 or > 1440 || input.BreakMinutes < 0 || input.BreakMinutes >= input.DurationMinutes || input.RequiredCount is < 1 or > 500) throw new ArgumentException("Şablon saat/mola/kapasite alanlarını kontrol edin.");
        using var reason = AuditContext.UseReason(AuditContext.ValidateReason(input.Reason)); await using var w = await SqlUnitOfWork.OpenAsync(connectionString, ct); await ProjectAuthorization.DemandAsync(w, user, input.ProjectId, ProjectAccess.PlanShifts, ct);
        if (input.TeamId.HasValue) { using var team = w.Command("SELECT COUNT(*) FROM dbo.ProjectTeams WITH(HOLDLOCK) WHERE TeamId=@team AND ProjectId=@project AND (@active=0 OR IsActive=1)"); team.Parameters.Add("@active", SqlDbType.Bit).Value = input.Active; Id(team, "@team", input.TeamId); Id(team, "@project", input.ProjectId); if (Convert.ToInt32(await team.ExecuteScalarAsync(ct)) != 1) throw new InvalidOperationException("Ekip bulunamadı/etkin değil."); }
        var row = await RowAsync(w, "ShiftTemplates", "TemplateId", input.TemplateId, ct);
        if (row != null) { ProjectRow(row, input.ProjectId); if (input.Version == null) { if (row.Field<string>("Name") == name && row.Field<string>("Site") == site && row.Field<Guid?>("TeamId") == input.TeamId && row.Field<int>("StartMinute") == input.StartMinute && row.Field<int>("DurationMinutes") == input.DurationMinutes && row.Field<int>("BreakMinutes") == input.BreakMinutes && row.Field<int>("RequiredCount") == input.RequiredCount && row.Field<bool>("IsActive") == input.Active) { await w.CommitAsync(ct); return; } throw new InvalidOperationException("Şablon kimliği daha önce kullanılmış."); } Version(row, input.Version); } else if (input.Version != null) throw new InvalidOperationException("Şablon bulunamadı.");
        using var c = w.Command(row == null ? "INSERT dbo.ShiftTemplates(TemplateId,ProjectId,TeamId,Name,Site,StartMinute,DurationMinutes,BreakMinutes,RequiredCount,IsActive) VALUES(@id,@project,@team,@name,@site,@start,@duration,@break,@count,@active)" : "UPDATE dbo.ShiftTemplates SET TeamId=@team,Name=@name,Site=@site,StartMinute=@start,DurationMinutes=@duration,BreakMinutes=@break,RequiredCount=@count,IsActive=@active WHERE TemplateId=@id"); Id(c, "@id", input.TemplateId); Id(c, "@project", input.ProjectId); Id(c, "@team", input.TeamId); c.Text("@name", name, 100); c.Text("@site", site, 100); c.Parameters.Add("@start", SqlDbType.Int).Value = input.StartMinute; c.Parameters.Add("@duration", SqlDbType.Int).Value = input.DurationMinutes; c.Parameters.Add("@break", SqlDbType.Int).Value = input.BreakMinutes; c.Parameters.Add("@count", SqlDbType.Int).Value = input.RequiredCount; c.Parameters.Add("@active", SqlDbType.Bit).Value = input.Active; await c.ExecuteNonQueryAsync(ct); await w.CommitAsync(ct);
    }
    internal async Task CreateShiftAsync(Wire.ShiftCreate input, CancellationToken ct)
    {
        if (DesktopConnection.IsRemote(connectionString)) { await RemoteApi.For(connectionString, user).Done("schedule/create", input, ct); return; }
        var day = EmploymentService.Day(input.Day)!.Value; if (input.ShiftId == Guid.Empty) throw new ArgumentException("Vardiya kimliği gerekiyor."); string text = AuditContext.ValidateReason(input.Reason); using var reason = AuditContext.UseReason(text); await using var w = await SqlUnitOfWork.OpenAsync(connectionString, ct); await ProjectAuthorization.DemandAsync(w, user, input.ProjectId, ProjectAccess.PlanShifts, ct);
        var prior = await RowAsync(w, "PlannedShifts", "ShiftId", input.ShiftId, ct); if (prior != null) { ProjectRow(prior, input.ProjectId); if (prior.Field<Guid>("TemplateId") != input.TemplateId || prior.Field<DateTime>("LocalStart").Date != day || !((byte[])prior["TemplateVersion"]).SequenceEqual(input.TemplateVersion) || prior.Field<string>("CreateReason") != text) throw new InvalidOperationException("İşlem kimliği farklı vardiya için kullanılmış."); await w.CommitAsync(ct); return; }
        var t = await RowAsync(w, "ShiftTemplates", "TemplateId", input.TemplateId, ct) ?? throw new InvalidOperationException("Şablon bulunamadı."); ProjectRow(t, input.ProjectId); Version(t, input.TemplateVersion); if (!t.Field<bool>("IsActive")) throw new InvalidOperationException("Şablon pasif."); var start = day.AddMinutes(t.Field<int>("StartMinute")); var end = start.AddMinutes(t.Field<int>("DurationMinutes")); var utc = SchedulingRules.UtcRange(start, end); await ProjectRangeAsync(w, input.ProjectId, t.Field<Guid?>("TeamId"), start, end, ct);
        string site = t.Field<string>("Site")!; if (site.Length == 0) { using var location = w.Command("SELECT COALESCE(Site,N'') FROM dbo.FinanceProjects WHERE ProjectId=@id"); Id(location, "@id", input.ProjectId); site = (string)(await location.ExecuteScalarAsync(ct))!; }
        using var c = w.Command(@"INSERT dbo.PlannedShifts(ShiftId,ProjectId,TemplateId,TemplateVersion,TeamId,Name,Site,LocalStart,LocalEnd,StartUtc,EndUtc,TimeZoneId,BreakMinutes,RequiredCount,CreatedBy,CreateReason)
 VALUES(@id,@project,@template,@version,@team,@name,@site,@start,@end,@utcstart,@utcend,@zone,@break,@count,@actor,@reason)"); Id(c, "@id", input.ShiftId); Id(c, "@project", input.ProjectId); Id(c, "@template", input.TemplateId); c.Parameters.Add("@version", SqlDbType.Binary, 8).Value = input.TemplateVersion; Id(c, "@team", t.Field<Guid?>("TeamId")); c.Text("@name", t.Field<string>("Name")!, 100); c.Text("@site", site, 100); Time(c, "@start", start); Time(c, "@end", end); Time(c, "@utcstart", utc.Start); Time(c, "@utcend", utc.End); c.Text("@zone", DailyClosingService.BusinessZone.Id, 100); c.Parameters.Add("@break", SqlDbType.Int).Value = t.Field<int>("BreakMinutes"); c.Parameters.Add("@count", SqlDbType.Int).Value = t.Field<int>("RequiredCount"); c.Text("@actor", user.Username); c.Text("@reason", text, 500); await c.ExecuteNonQueryAsync(ct); await w.CommitAsync(ct);
    }
    internal async Task AssignAsync(Wire.ShiftPerson input, CancellationToken ct)
    {
        if (DesktopConnection.IsRemote(connectionString)) { await RemoteApi.For(connectionString, user).Done("schedule/assign", input, ct); return; }
        if (!Enum.IsDefined(input.Group) || input.AssignmentId == Guid.Empty) throw new ArgumentException("Geçerli kişi/grup seçin."); using var reason = AuditContext.UseReason(AuditContext.ValidateReason(input.Reason)); await using var w = await SqlUnitOfWork.OpenAsync(connectionString, ct); await ProjectAuthorization.DemandAsync(w, user, input.ProjectId, ProjectAccess.PlanShifts, ct);
        var s = await RowAsync(w, "PlannedShifts", "ShiftId", input.ShiftId, ct) ?? throw new InvalidOperationException("Vardiya bulunamadı."); ProjectRow(s, input.ProjectId);
        var prior = await RowAsync(w, "ShiftAssignments", "ShiftAssignmentId", input.AssignmentId, ct); if (prior != null) { if (prior.Field<Guid>("ShiftId") != input.ShiftId || prior.Field<Guid>("PersonId") != input.PersonId || prior.Field<int>("PersonnelGroup") != (int)input.Group || !prior.IsNull("CancelledUtc")) throw new InvalidOperationException("Atama kimliği kullanılmış/iptal edilmiş."); await w.CommitAsync(ct); return; }
        Version(s, input.ShiftVersion); if (s.Field<string>("Status") != "Draft") throw new InvalidOperationException("Yalnız taslak vardiyaya kişi eklenir."); var start = DateTime.SpecifyKind(s.Field<DateTime>("LocalStart"), DateTimeKind.Unspecified); var end = DateTime.SpecifyKind(s.Field<DateTime>("LocalEnd"), DateTimeKind.Unspecified); await ProjectRangeAsync(w, input.ProjectId, s.Field<Guid?>("TeamId"), start, end, ct); var target = await TargetAsync(w, input.ProjectId, s.Field<Guid?>("TeamId"), input.PersonId, (PersonnelGroup)input.Group, input.PersonVersion, start, end, ct); await SchedulingRules.ClearAsync(w, input.PersonId, start, end, null, null, true, ct);
        using (var count = w.Command("SELECT COUNT(*) FROM dbo.ShiftAssignments WITH(UPDLOCK,HOLDLOCK) WHERE ShiftId=@id AND CancelledUtc IS NULL")) { Id(count, "@id", input.ShiftId); if (Convert.ToInt32(await count.ExecuteScalarAsync(ct)) >= s.Field<int>("RequiredCount")) throw new InvalidOperationException("Vardiya kapasitesi dolu."); }
        using (var c = w.Command("INSERT dbo.ShiftAssignments(ShiftAssignmentId,ShiftId,PersonId,EmploymentId,PersonnelGroup,RosterAssignmentId,CreatedBy) VALUES(@id,@shift,@person,@employment,@group,@roster,@actor)")) { Id(c, "@id", input.AssignmentId); Id(c, "@shift", input.ShiftId); Id(c, "@person", input.PersonId); Id(c, "@employment", target.Employment); c.Parameters.Add("@group", SqlDbType.Int).Value = (int)input.Group; Id(c, "@roster", target.Roster); c.Text("@actor", user.Username); await c.ExecuteNonQueryAsync(ct); }
        await TouchAsync(w, input.ShiftId, ct); await w.CommitAsync(ct);
    }
    private static async Task TouchAsync(IUnitOfWork w, Guid shift, CancellationToken ct) { using var c = w.Command("UPDATE dbo.PlannedShifts SET RequiredCount=RequiredCount WHERE ShiftId=@id"); Id(c, "@id", shift); await c.ExecuteNonQueryAsync(ct); }
    internal async Task CancelAssignmentAsync(Wire.ShiftPersonCancel input, CancellationToken ct)
    {
        if (DesktopConnection.IsRemote(connectionString)) { await RemoteApi.For(connectionString, user).Done("schedule/unassign", input, ct); return; }
        using var reason = AuditContext.UseReason(AuditContext.ValidateReason(input.Reason)); await using var w = await SqlUnitOfWork.OpenAsync(connectionString, ct); await ProjectAuthorization.DemandAsync(w, user, input.ProjectId, ProjectAccess.PlanShifts, ct); var s = await RowAsync(w, "PlannedShifts", "ShiftId", input.ShiftId, ct) ?? throw new InvalidOperationException("Vardiya yok."); ProjectRow(s, input.ProjectId); var a = await RowAsync(w, "ShiftAssignments", "ShiftAssignmentId", input.AssignmentId, ct) ?? throw new InvalidOperationException("Atama yok."); if (a.Field<Guid>("ShiftId") != input.ShiftId) throw new UnauthorizedAccessException("Atama bu vardiyada değil."); if (!a.IsNull("CancelledUtc")) { await w.CommitAsync(ct); return; }
        Version(s, input.ShiftVersion); Version(a, input.Version); if (s.Field<string>("Status") != "Draft") throw new InvalidOperationException("Yayınlanmış vardiya ataması değiştirilemez; vardiyayı iptal edip yeniden oluşturun."); await SchedulingRules.LockPersonAsync(w, a.Field<Guid>("PersonId"), ct); using var c = w.Command("UPDATE dbo.ShiftAssignments SET CancelledUtc=SYSUTCDATETIME(),CancelledBy=@actor WHERE ShiftAssignmentId=@id"); Id(c, "@id", input.AssignmentId); c.Text("@actor", user.Username); await c.ExecuteNonQueryAsync(ct); await TouchAsync(w, input.ShiftId, ct); await w.CommitAsync(ct);
    }
    internal async Task StateAsync(Wire.ShiftState input, CancellationToken ct)
    {
        if (DesktopConnection.IsRemote(connectionString)) { await RemoteApi.For(connectionString, user).Done("schedule/state", input, ct); return; }
        if (input.State is not ("Published" or "Cancelled")) throw new ArgumentException("Geçersiz vardiya durumu."); using var reason = AuditContext.UseReason(AuditContext.ValidateReason(input.Reason)); await using var w = await SqlUnitOfWork.OpenAsync(connectionString, ct); await ProjectAuthorization.DemandAsync(w, user, input.ProjectId, ProjectAccess.PlanShifts, ct); var s = await RowAsync(w, "PlannedShifts", "ShiftId", input.ShiftId, ct) ?? throw new InvalidOperationException("Vardiya yok."); ProjectRow(s, input.ProjectId); if (s.Field<string>("Status") == input.State) { await w.CommitAsync(ct); return; }
        Version(s, input.Version); if (s.Field<string>("Status") == "Cancelled" || (input.State == "Published" && s.Field<string>("Status") != "Draft")) throw new InvalidOperationException("Vardiya artık bu duruma geçirilemez.");
        if (input.State == "Published")
        { var start = DateTime.SpecifyKind(s.Field<DateTime>("LocalStart"), DateTimeKind.Unspecified); var end = DateTime.SpecifyKind(s.Field<DateTime>("LocalEnd"), DateTimeKind.Unspecified); await ProjectRangeAsync(w, input.ProjectId, s.Field<Guid?>("TeamId"), start, end, ct); using var q = w.Command("SELECT PersonId,EmploymentId,PersonnelGroup,RosterAssignmentId FROM dbo.ShiftAssignments WITH(UPDLOCK,HOLDLOCK) WHERE ShiftId=@id AND CancelledUtc IS NULL ORDER BY PersonId"); Id(q, "@id", input.ShiftId); var assignments = await q.TableAsync(ct); foreach (DataRow a in assignments.Rows) { var target = await TargetAsync(w, input.ProjectId, s.Field<Guid?>("TeamId"), a.Field<Guid>("PersonId"), (PersonnelGroup)a.Field<int>("PersonnelGroup"), null, start, end, ct); if (target.Employment != a.Field<Guid>("EmploymentId") || target.Roster != a.Field<Guid>("RosterAssignmentId")) throw new InvalidOperationException("Vardiya kişinin önceki atama/dönemine ait; yeniden planlayın."); await SchedulingRules.ClearAsync(w, a.Field<Guid>("PersonId"), start, end, input.ShiftId, null, true, ct); } }
        if (input.State == "Cancelled") { using var timesheets = w.Command("SELECT COUNT(*) FROM dbo.Timesheets T WITH(HOLDLOCK) JOIN dbo.ShiftAssignments A ON A.ShiftAssignmentId=T.ShiftAssignmentId WHERE A.ShiftId=@id AND T.Status<>N'Cancelled'"); Id(timesheets,"@id",input.ShiftId); if(Convert.ToInt32(await timesheets.ExecuteScalarAsync(ct))>0) throw new InvalidOperationException("Vardiyaya bağlı puantaj var. Önce puantajı gerekçeli yeniden açıp iptal edin."); }
        using var c = w.Command(input.State == "Published" ? "UPDATE dbo.PlannedShifts SET Status=N'Published',PublishedUtc=SYSUTCDATETIME(),PublishedBy=@actor WHERE ShiftId=@id" : "UPDATE dbo.PlannedShifts SET Status=N'Cancelled',CancelledUtc=SYSUTCDATETIME(),CancelledBy=@actor WHERE ShiftId=@id"); Id(c, "@id", input.ShiftId); c.Text("@actor", user.Username); await c.ExecuteNonQueryAsync(ct); await w.CommitAsync(ct);
    }
